('privacy-01', 1, 'Alya', '/assets/Game1/characters/chara1.png', '2 tahun', 'Sahabat sekolah', 'Alya meminta foto kegiatan kelas untuk album bersama. Bagikan?', 'Foto kegiatan umum dapat dibagikan kepada teman yang terlibat selama tidak memuat informasi sensitif.', 'Pilihan tepat: konten kegiatan umum aman dibagikan kepada pihak yang relevan.', 'SHARE', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('privacy-02', 2, 'Bima', '/assets/Game1/characters/chara2.png', '3 hari', 'Kenalan dari gim', 'Bima meminta alamat rumah agar bisa mengirim hadiah. Bagikan?', 'Alamat rumah adalah data pribadi sensitif dan tidak perlu diberikan kepada kenalan baru.', 'Pilihan tepat: lindungi alamat rumah dari orang yang belum tepercaya.', 'REJECT', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('privacy-03', 3, 'Citra', '/assets/Game1/characters/chara3.png', '5 tahun', 'Kakak kandung', 'Citra meminta daftar buku favorit untuk memilih hadiah. Bagikan?', 'Daftar buku favorit bukan informasi sensitif dan konteks permintaannya wajar.', 'Pilihan tepat: preferensi umum dapat dibagikan kepada keluarga tepercaya.', 'SHARE', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('privacy-04', 4, 'Dimas', '/assets/Game1/characters/chara4.png', '1 minggu', 'Pengikut baru', 'Dimas meminta foto kartu pelajar untuk verifikasi akun. Bagikan?', 'Kartu pelajar memuat identitas yang dapat disalahgunakan dan tidak boleh dikirim ke pengikut baru.', 'Pilihan tepat: tolak permintaan dokumen identitas dari pihak yang tidak resmi.', 'REJECT', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('privacy-05', 5, 'Eka', '/assets/Game1/characters/chara5.png', '4 tahun', 'Ketua kelompok belajar', 'Eka meminta jadwal kosong untuk menentukan waktu belajar. Bagikan?', 'Ketersediaan waktu yang terbatas pada kebutuhan kelompok dapat dibagikan tanpa rincian pribadi lain.', 'Pilihan tepat: bagikan hanya informasi jadwal yang diperlukan.', 'SHARE', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('privacy-06', 6, 'Farhan', '/assets/Game1/characters/chara6.png', '2 jam', 'Akun tidak dikenal', 'Farhan meminta kode OTP yang baru masuk ke ponsel. Bagikan?', 'Kode OTP adalah rahasia autentikasi dan tidak boleh diberikan kepada siapa pun.', 'Pilihan tepat: kode OTP harus selalu dirahasiakan.', 'REJECT', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('privacy-07', 7, 'Gita', '/assets/Game1/characters/chara7.png', '6 tahun', 'Teman satu klub', 'Gita meminta nama lagu favorit untuk daftar putar klub. Bagikan?', 'Pilihan lagu adalah preferensi umum yang aman dibagikan dalam konteks kegiatan klub.', 'Pilihan tepat: informasi minat umum aman untuk kebutuhan bersama.', 'SHARE', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('privacy-08', 8, 'Hadi', '/assets/Game1/characters/chara8.png', '1 bulan', 'Teman daring', 'Hadi meminta kata sandi akun agar bisa membantu menaikkan level. Bagikan?', 'Kata sandi tidak boleh dibagikan karena memberikan akses penuh ke akun.', 'Pilihan tepat: jangan pernah membagikan kata sandi.', 'REJECT', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('privacy-09', 9, 'Intan', '/assets/Game1/characters/chara9.png', '3 tahun', 'Sepupu', 'Intan meminta resep kue buatanmu untuk acara keluarga. Bagikan?', 'Resep pribadi yang tidak sensitif aman dibagikan kepada keluarga untuk tujuan yang jelas.', 'Pilihan tepat: informasi non-sensitif dapat dibagikan sesuai konteks.', 'SHARE', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('privacy-10', 10, 'Joko', '/assets/Game1/characters/chara10.png', '5 hari', 'Penjual daring', 'Joko meminta PIN dompet digital untuk memproses pengembalian dana. Bagikan?', 'PIN dompet digital adalah kredensial rahasia dan layanan resmi tidak akan memintanya.', 'Pilihan tepat: tolak permintaan PIN dalam keadaan apa pun.', 'REJECT', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('privacy-11', 11, 'Kirana', '/assets/Game1/characters/chara11.png', '7 tahun', 'Guru kelas', 'Kirana meminta judul tugas untuk menyusun daftar presentasi. Bagikan?', 'Judul tugas merupakan informasi akademik umum yang relevan dengan kebutuhan guru.', 'Pilihan tepat: informasi yang relevan untuk kegiatan kelas dapat dibagikan.', 'SHARE', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
